var sym=doc.GetElement(new ElementId(Tama.Args.Get(args,"typeId",0))) as FamilySymbol;
if(sym==null||sym.Category==null||sym.Category.Id.IntegerValue!=(int)BuiltInCategory.OST_Parking) throw new Exception("typeId is not a parking type.");
if(!sym.IsActive){sym.Activate();doc.Regenerate();}
var lvl=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name==Tama.Args.Get(args,"level",""));
double k=1/304.8;
var bays=args["bays"] as object[];
var created=new List<int>();
foreach(var o in bays){
 var a=o as object[];
 string id=Convert.ToString(a[0]);double x=Convert.ToDouble(a[1]),y=Convert.ToDouble(a[2]),t=Convert.ToDouble(a[3]);
 var p=new XYZ(x*k,y*k,lvl.Elevation);
 var fi=doc.Create.NewFamilyInstance(p,sym,lvl,Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
 if(Math.Abs(t)>0.001)ElementTransformUtils.RotateElement(doc,fi.Id,Line.CreateBound(p,p+XYZ.BasisZ),t*Math.PI/180.0);
 fi.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).Set(id);
 created.Add(fi.Id.IntegerValue);
}
return new{count=created.Count,first=created.First(),last=created.Last()};
